// streamReaderModelActions is the operation vocabulary both legs drive.
//
// One constructor per method shape, from the engine's action set rather
// than hand-written closures: the constructors record inputs and outputs
// into the trace a law reads, compare the two sides the same way for every
// action, and shrink a failing sequence to the shortest one that still
// fails.
func streamReaderModelActions(fx StreamReaderFixture) []model.Action[StreamReader] {
	values := streamReaderModelValues(fx)
	return []model.Action[StreamReader]{
		action.Writer("Add", values,
			func(ctx context.Context, s streamreader.StreamReader, v streamreader.Value) error {
				return s.Add(ctx, v)
			}),
		action.Stream("List",
			func(ctx context.Context, s streamreader.StreamReader) ([]streamreader.Value, error) {
				var out []streamreader.Value
				for v, err := range s.List(ctx) {
					if err != nil {
						return nil, err
					}
					out = append(out, v)
				}
				return out, nil
			}),
	}
}

